33: static int allocate_minor(struct ocxl_file_info *info)
34: {
35: 	int minor;
36: 
37: 	mutex_lock(&minors_idr_lock);
38: 	minor = idr_alloc(&minors_idr, info, 0, OCXL_NUM_MINORS, GFP_KERNEL);
39: 	mutex_unlock(&minors_idr_lock);
40: 	return minor;
41: }
