43: static void free_minor(struct ocxl_file_info *info)
44: {
45: 	mutex_lock(&minors_idr_lock);
46: 	idr_remove(&minors_idr, MINOR(info->dev.devt));
47: 	mutex_unlock(&minors_idr_lock);
48: }
